# Supplementary batch: harvest biochemistry integration with transcriptomics.
#
# Produces three figures from the CSVs generated by
# biochemistry_harvest_prep.py:
#
#   S61 — validation: per-sample expression vs biochemistry at Harvest
#         (partial-season + per-season Spearman rho)
#   S62 — cohort trajectory: biochem ~ years-since-infection per season
#         (mirrors Q1 biphasic-recovery transcriptomic finding)
#   S63 — Season x Infection ANOVA on harvest juice chemistry
#         (mirrors Q4 inverted seasonal trajectory)

suppressPackageStartupMessages({
  library(ggplot2); library(dplyr); library(tidyr); library(readr)
  library(patchwork); library(scales); library(ggrepel)
})

HERE <- "/Users/prempratapsingh/Data_Analysis/figures/scripts_R"
source(file.path(HERE, "theme_grbv.R"))

DATA_ROOT <- "/Users/prempratapsingh/Data_Analysis"
OUT_DIR   <- "/Users/prempratapsingh/Data_Analysis/figures/supp"
dir.create(OUT_DIR, recursive = TRUE, showWarnings = FALSE)

merged  <- read_csv(file.path(DATA_ROOT, "biochemistry_transcriptome_harvest_merged.csv"),
                    show_col_types = FALSE)
biochem <- read_csv(file.path(DATA_ROOT, "biochemistry_harvest.csv"),
                    show_col_types = FALSE)
val     <- read_csv(file.path(DATA_ROOT, "biochemistry_validation_correlations.csv"),
                    show_col_types = FALSE)
traj    <- read_csv(file.path(DATA_ROOT, "biochemistry_cohort_trajectory.csv"),
                    show_col_types = FALSE)
aov     <- read_csv(file.path(DATA_ROOT, "biochemistry_season_infection_anova.csv"),
                    show_col_types = FALSE)

merged  <- merged  %>% mutate(Sampling_Season = factor(Sampling_Season, levels = c(2021, 2022)))
biochem <- biochem %>% mutate(Sampling_Season = factor(Sampling_Season, levels = c(2021, 2022)))

fmt_p <- function(p) ifelse(is.na(p), "NA",
                     ifelse(p < 1e-3, sprintf("%.1e", p),
                     ifelse(p < 0.01, sprintf("%.3f", p),
                                      sprintf("%.2f", p))))

# =================================================================
# S61 — validation scatter grid
# =================================================================
panels <- tibble::tribble(
  ~predictor,       ~biochem, ~xlab,
  "SPS1",           "Brix",   "SPS1 (log2 CPM)",
  "SPS1",           "Malic",  "SPS1 (log2 CPM)",
  "MBF1c",          "Brix",   "MBF1c (log2 CPM)",
  "LOC100266309",   "Brix",   "LOC100266309 (log2 CPM)",
  "sHSP_score",     "Brix",   "sHSP module score (z)",
  "Titer_log10",    "Brix",   "log10(viral titer)"
)

make_valid_panel <- function(pred, bio, xlab) {
  stats_row <- val %>% filter(predictor == pred, biochem == bio)
  sub <- merged %>% select(all_of(c(pred, bio)), Sampling_Season) %>%
    setNames(c("x", "y", "Season")) %>% tidyr::drop_na()

  # v2 fix: rho annotations moved from subtitle into the panel top-right as
  # a 3-line text block, and regression lines are clipped to per-season data
  # ranges via fullrange=FALSE (default, but made explicit) + coord range
  # control so lines don't extrapolate into empty regions.
  title <- sprintf("%s vs %s", pred, bio)
  ann_text <- sprintf(
    "partial \u03c1 = %.2f, p = %s\n2021: \u03c1 = %.2f, p = %s\n2022: \u03c1 = %.2f, p = %s",
    stats_row$rho_partial_season, fmt_p(stats_row$p_partial_season),
    stats_row$rho_2021, fmt_p(stats_row$p_2021),
    stats_row$rho_2022, fmt_p(stats_row$p_2022))

  ggplot(sub, aes(x = x, y = y, colour = Season)) +
    geom_smooth(method = "lm", se = FALSE, linewidth = 0.6,
                formula = y ~ x, na.rm = TRUE, fullrange = FALSE) +
    geom_point(size = 1.7, alpha = 0.9, stroke = 0.3, colour = "black",
               shape = 21, aes(fill = Season)) +
    annotate("label", x = Inf, y = Inf, label = ann_text,
             hjust = 1.02, vjust = 1.05, family = "Arial",
             size = 2.1, colour = "grey20", lineheight = 1.0,
             fill = alpha("white", 0.85),
             label.size = 0, label.padding = unit(1.5, "pt")) +
    scale_colour_manual(values = pal_season, guide = "none") +
    scale_fill_manual(values = pal_season, name = "Season") +
    labs(title = title, x = xlab, y = bio) +
    theme_grbv(base_size = 8) +
    theme(plot.title = element_text(face = "bold", size = 8.5))
}

p_list <- purrr::pmap(list(panels$predictor, panels$biochem, panels$xlab),
                     make_valid_panel)

S61 <- wrap_plots(p_list, ncol = 3, nrow = 2) +
  plot_layout(guides = "collect") +
  plot_annotation(
    title = "Fig. S61 — Phenotypic validation of transcriptomic findings at Harvest",
    subtitle = "Per-sample expression (log2 CPM) or module score vs juice chemistry; n=33 paired samples. Partial rho controls for season.",
    theme = theme_grbv(base_size = 9) +
      theme(plot.title = element_text(face = "bold", size = 11),
            plot.subtitle = element_text(size = 8, colour = "grey25"))
  ) &
  theme(legend.position = "bottom", legend.direction = "horizontal")

save_grbv(S61, file.path(OUT_DIR, "S61_biochem_validation"),
          width_mm = 183, height_mm = 165)

# =================================================================
# S62 — cohort trajectory (Brix, pH, TA, Malic vs YSI per season)
# =================================================================
vars62 <- c("Brix", "pH", "TA", "Malic")

make_traj_panel <- function(v, season) {
  rbp <- biochem %>% filter(Sampling_Season == season, Infection_Group == "RB(+)") %>%
    select(YSI_years, value = all_of(v)) %>% tidyr::drop_na()
  rbn_vec <- biochem %>% filter(Sampling_Season == season,
                                Infection_Group == "RB(-)") %>%
    pull(all_of(v))
  rbn_mean <- mean(rbn_vec, na.rm = TRUE)
  trow <- traj %>% filter(season == !!as.integer(as.character(season)),
                          biochem == v)

  # v2 fix: the RB(-) reference line often sat far outside the RB(+) data
  # range (e.g. 2021 Malic) and dominated the y-axis. Drop the hline and
  # show the RB(-) mean as a small inline annotation instead, letting the
  # y-axis auto-scale to the RB(+) cohort points where the story lives.
  title <- sprintf("%s — %s", season, v)
  sub_c <- sprintf("slope = %+.3f/yr, r = %.2f, p = %s\nRB(\u2212) mean = %.2f",
                   trow$slope_per_year, trow$r, fmt_p(trow$p), rbn_mean)

  ggplot(rbp, aes(YSI_years, value)) +
    geom_smooth(method = "lm", se = TRUE, colour = "black",
                fill = "grey80", linewidth = 0.5, formula = y ~ x,
                alpha = 0.35, fullrange = FALSE) +
    geom_point(size = 2.0, fill = unname(pal_season[as.character(season)]),
               colour = "black", shape = 21, stroke = 0.3) +
    labs(title = title, subtitle = sub_c,
         x = "Years since infection", y = v) +
    theme_grbv(base_size = 8) +
    theme(plot.title    = element_text(face = "bold", size = 8.5),
          plot.subtitle = element_text(size = 6.3, colour = "grey25"))
}

g62 <- list()
for (v in vars62) for (s in levels(biochem$Sampling_Season)) {
  g62[[length(g62) + 1]] <- make_traj_panel(v, s)
}

S62 <- wrap_plots(g62, ncol = 4, nrow = 2, byrow = FALSE) +
  plot_annotation(
    title = "Fig. S62 — Cohort trajectory at Harvest: biochemistry vs years-since-infection",
    subtitle = "RB(+) samples only; each panel auto-scales to RB(+) data. RB(\u2212) season mean noted in per-panel subtitle.",
    theme = theme_grbv(base_size = 9) +
      theme(plot.title    = element_text(face = "bold", size = 11),
            plot.subtitle = element_text(size = 8, colour = "grey25"))
  )

save_grbv(S62, file.path(OUT_DIR, "S62_biochem_cohort_trajectory"),
          width_mm = 210, height_mm = 125)

# =================================================================
# S63 — Season x Infection ANOVA on juice chemistry
# =================================================================
vars63 <- c("Brix", "pH", "TA", "Malic", "YAN", "NH3")

long_aov <- biochem %>%
  select(Sampling_Season, Infection_Group, all_of(vars63)) %>%
  tidyr::pivot_longer(all_of(vars63), names_to = "biochem", values_to = "value") %>%
  mutate(
    biochem = factor(biochem, levels = vars63),
    grp = factor(paste(Sampling_Season, Infection_Group),
                 levels = c("2021 RB(-)", "2021 RB(+)", "2022 RB(-)", "2022 RB(+)"))
  )

group_fill <- c(
  "2021 RB(-)" = "#9ecae1",
  "2021 RB(+)" = unname(pal_season["2021"]),
  "2022 RB(-)" = "#fde0ef",
  "2022 RB(+)" = unname(pal_season["2022"])
)

aov_label <- function(v) {
  r <- aov %>% filter(biochem == v)
  sprintf("Season p=%s, Infection p=%s\nSeason x Infection p=%s",
          fmt_p(r$p_season), fmt_p(r$p_infection), fmt_p(r$p_interaction))
}

make_aov_panel <- function(v) {
  sub <- long_aov %>% filter(biochem == v)
  ggplot(sub, aes(grp, value)) +
    geom_boxplot(aes(fill = grp), outlier.shape = NA,
                 width = 0.65, linewidth = 0.4, alpha = 0.85) +
    geom_jitter(width = 0.12, size = 1.3, alpha = 0.7,
                colour = "black", shape = 21, fill = "white", stroke = 0.2) +
    scale_fill_manual(values = group_fill, guide = "none") +
    labs(title = v, subtitle = aov_label(v), x = NULL, y = v) +
    theme_grbv(base_size = 8) +
    theme(axis.text.x = element_text(angle = 25, hjust = 1, size = 6.5),
          plot.subtitle = element_text(size = 6.5, colour = "grey25"))
}

g63 <- lapply(vars63, make_aov_panel)

S63 <- wrap_plots(g63, ncol = 3, nrow = 2) +
  plot_annotation(
    title = "Fig. S63 — Season x Infection ANOVA on harvest juice chemistry",
    subtitle = "Two-way ANOVA on n=33 samples; boxes show median + IQR, dots show individual samples.",
    theme = theme_grbv(base_size = 9) +
      theme(plot.title = element_text(face = "bold", size = 11),
            plot.subtitle = element_text(size = 8, colour = "grey25"))
  )

save_grbv(S63, file.path(OUT_DIR, "S63_biochem_season_infection"),
          width_mm = 183, height_mm = 135)

cat("supp_biochem.R: wrote S61, S62, S63 to", OUT_DIR, "\n")
